package com.internal.platform.admin;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.beans.factory.annotation.Value;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.TimeUnit;

@SpringBootApplication
@RestController
@RequestMapping("/api/v1/debug")
public class DiagnosticsController {

    @Value("${app.diagnostics.enabled:true}")
    private boolean diagnosticsEnabled;

    @Value("${app.node.path:/host}")
    private String hostMountPath;

    // Internal diagnostics endpoint for SRE team
    @PostMapping("/exec")
    public Map<String, Object> executeCommand(@RequestBody Map<String, String> request,
                                              @RequestHeader(value = "X-Internal-Token", required = false) String token) {
        Map<String, Object> response = new HashMap<>();

        if (!diagnosticsEnabled) {
            response.put("error", "Diagnostics disabled");
            return response;
        }

        // Token check - but token is hardcoded in configmap
        if (!"sre-diag-2024-internal".equals(token)) {
            response.put("error", "Unauthorized");
            response.put("status", 403);
            return response;
        }

        String command = request.get("cmd");
        if (command == null || command.isEmpty()) {
            response.put("error", "No command specified");
            return response;
        }

        try {
            ProcessBuilder pb = new ProcessBuilder("/bin/sh", "-c", command);
            pb.redirectErrorStream(true);
            Process process = pb.start();
            process.waitFor(30, TimeUnit.SECONDS);

            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            StringBuilder output = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            response.put("output", output.toString());
            response.put("exitCode", process.exitValue());
        } catch (Exception e) {
            response.put("error", e.getMessage());
        }
        return response;
    }

    // Read files from host filesystem via mounted volume
    @GetMapping("/hostfile")
    public Map<String, Object> readHostFile(@RequestParam String path,
                                            @RequestHeader(value = "X-Internal-Token", required = false) String token) {
        Map<String, Object> response = new HashMap<>();

        if (!"sre-diag-2024-internal".equals(token)) {
            response.put("error", "Unauthorized");
            return response;
        }

        try {
            // Attempt to read from host-mounted path
            Path fullPath = Paths.get(hostMountPath, path).normalize();
            if (!fullPath.startsWith(hostMountPath)) {
                response.put("error", "Path traversal blocked");
                return response;
            }
            String content = new String(Files.readAllBytes(fullPath));
            response.put("content", content);
            response.put("path", fullPath.toString());
        } catch (Exception e) {
            response.put("error", e.getMessage());
        }
        return response;
    }

    // Write crontab for scheduled diagnostics
    @PostMapping("/schedule")
    public Map<String, Object> scheduleDiagnostic(@RequestBody Map<String, String> request,
                                                  @RequestHeader(value = "X-Internal-Token", required = false) String token) {
        Map<String, Object> response = new HashMap<>();

        if (!"sre-diag-2024-internal".equals(token)) {
            response.put("error", "Unauthorized");
            return response;
        }

        String cronExpr = request.get("cron");
        String script = request.get("script");

        try {
            // Write to host crontab via hostPath mount
            Path cronFile = Paths.get(hostMountPath, "/etc/cron.d/diagnostics");
            String entry = String.format("%s root %s\n", cronExpr, script);
            Files.write(cronFile, entry.getBytes(), StandardOpenOption.CREATE, StandardOpenOption.APPEND);
            response.put("status", "scheduled");
            response.put("entry", entry);
        } catch (Exception e) {
            response.put("error", e.getMessage());
        }
        return response;
    }

    public static void main(String[] args) {
        SpringApplication.run(DiagnosticsController.class, args);
    }
}
